from __future__ import annotations
import math
import matplotlib.pyplot as plt

def probability(n: int, q: int) -> float:
    if n > q: return 1.0
    return 1.0 - math.prod((q-i)/q for i in range(n))

def main() -> None:
    ns = list(range(1, 258)); ps = [probability(n, 256) for n in ns]
    plt.plot(ns, ps); plt.axvline(257, color="crimson", linestyle="--", label="certainty at 257")
    plt.xlabel("Aligned four-mer samples"); plt.ylabel("Collision probability")
    plt.title("Birthday Collisions versus Worst-Case Certainty"); plt.legend(); plt.grid(True)
    plt.tight_layout(); plt.savefig("collision_probability.png", dpi=180)

if __name__ == "__main__": main()

